"""Embed the same buildless page used by the localhost preview."""
from pathlib import Path

root = Path(__file__).resolve().parent
page = (root / "site/index.html").read_text()
assert ')BENCHHTML"' not in page
(root / "BenchPage.h").write_text(
    '#pragma once\n#include <Arduino.h>\n'
    '// Generated by embed-page.py from site/index.html.\n'
    'const char kBenchPage[] PROGMEM = R"BENCHHTML(' + page + ')BENCHHTML";\n'
)
